static dan_str dl_LTSdelano_str(const dl_LTSdelano *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dt_Sdelano_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LTSdelano_find(const dl_LTSdelano *l, dt_Sdelano b) {
    for (int64_t i = 0; i < l->len; i++) { dt_Sdelano a = l->items[i]; if (dt_Sdelano_eq(a, b)) return i; }
    return -1;
}
static bool dl_LTSdelano_contains(const dl_LTSdelano *l, dt_Sdelano b) { return dl_LTSdelano_find(l, b) >= 0; }
static bool dl_LTSdelano_eq(const dl_LTSdelano *x, const dl_LTSdelano *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dt_Sdelano a = x->items[i]; dt_Sdelano b = y->items[i]; if (!(dt_Sdelano_eq(a, b))) return false; }
    return true;
}


