static bool dm_DsTproverkau2eSoobshhenie_eq(const dm_DsTproverkau2eSoobshhenie *x, const dm_DsTproverkau2eSoobshhenie *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsTproverkau2eSoobshhenie_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dt_proverkau2eSoobshhenie a = x->vals[e]; dt_proverkau2eSoobshhenie b = y->vals[f];
        if (!(dt_proverkau2eSoobshhenie_eq(a, b))) return false;
    }
    return true;
}


